const data = $input.item.json.output;
if (!data) { return { json: { pageContent: "No data extracted", metadata: {} } }; }
const typeLabel = $input.first().json.output.transaction_type === 'income' ? 'รายรับ' : 'รายจ่าย';
const contentString = `ข้อมูลใบเสร็จ (${typeLabel}):
ผู้ชำระเงิน: ${$input.first().json.output.payer_name || '-'}
ผู้รับเงิน: ${$input.first().json.output.Recipient_name || '-'}
วันที่: ${$input.first().json.output.invoice_date || '-'}
ยอดรวมสุทธิ: ${$input.first().json.output.total_amount || '-'} บาท
กิจกรรม: ${$input.first().json.output.activity || '-'} `;
  return { json: { pageContent: contentString, metadata: { source: "receipt_analysis", timestamp: new Date().toISOString() } } };

const event = $json.body.events[0];
const source = event.source || {};
return {
  json: {
    lineUserId: source.userId || null,
    groupId: source.groupId || null,
    roomId: source.roomId || null,
    chatType: source.type || 'user'
  }
};

const query = $('Dashboard Webhook2').first().json.query || {};
let rows = $input.all().map(i => i.json).filter(r => r && r.month);

if (query.line_user_id) {
  rows = rows.filter(r => r.line_user_id === query.line_user_id);
} else if (query.group_id) {
  rows = rows.filter(r => r.group_id === query.group_id);
}

const rowsHtml = rows.map(r => `<tr><td>${r.month}</td><td>${r.display_name || r.line_user_id}</td>
<td style="text-align:right;color:#0a7d2c">${Number(r.income||0).toLocaleString()}</td>
<td style="text-align:right;color:#c0392b">${Number(r.expense||0).toLocaleString()}</td>
<td style="text-align:right;font-weight:bold">${Number(r.net||0).toLocaleString()}</td></tr>`).join('');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8">
<title>สรุปรายรับ-รายจ่ายรายเดือน</title>
<style>body{font-family:sans-serif;padding:24px;background:#f7f7f8}
table{border-collapse:collapse;width:100%;background:#fff}
th,td{padding:8px 12px;border-bottom:1px solid #eee}
th{background:#111;color:#fff;text-align:left}</style></head><body>
<h2>สรุปรายรับ-รายจ่ายรายเดือน</h2>
<table><thead><tr><th>เดือน</th><th>ผู้ใช้</th><th>รายรับ</th><th>รายจ่าย</th><th>คงเหลือสุทธิ</th></tr></thead>
<tbody>${rowsHtml || '<tr><td colspan=5>ไม่มีข้อมูล</td></tr>'}</tbody></table>
</body></html>`;

return { json: { html } };
